do $$declare d text;begin d:=pg_get_functiondef('private.fleet_handover_save(uuid,integer,jsonb)'::regprocedure);if position('هيكل نقل البضائع' in d)=0 then d:=replace(d,'if p_data->>''diagram_type''=''sedan''and','if p_data->>''diagram_type''=''cargo''and m->>''part''not in(''front_bumper'',''hood'',''windshield'',''roof'',''left_front_door'',''right_front_door'',''left_front_tire'',''right_front_tire'',''left_rear_tire'',''right_rear_tire'',''cargo_roof'',''cargo_left'',''cargo_right'',''cargo_rear'',''interior'',''other'')then raise exception ''موضع الملاحظة لا يخص هيكل نقل البضائع'';end if; if p_data->>''diagram_type''=''sedan''and');execute d;end if;end$$;
